-- cpu_top.vhd : MiniCPU-8 single-cycle core (ISA v2)
-- Fetch:   ROM read is combinational from the PC register.
-- Execute: regfile and data RAM reads are async; ALU/branch logic is
--          combinational.
-- Write:   PC, register file, flags and data RAM all update on the same rising
--          edge, so one instruction completes per clock cycle.
-- PROGRAM and RAM_INIT are generics generated by tools/assembler.py.
-- Reset suppresses register, flag and RAM writes; PC and flags are cleared.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.minicpu_pkg.all;

entity cpu_top is
  generic (
    PROGRAM  : rom_t;
    RAM_INIT : ram_init_t;
    CLK_FREQ : positive := 25_000_000;   -- UART baud reference
    BAUD     : positive := 115_200);
  port (
    clk       : in  std_logic;
    rst       : in  std_logic;                      -- synchronous, active high
    halted    : out std_logic;
    gpio_in   : in  byte_t;                          -- switches/buttons
    gpio_out  : out byte_t;                          -- LEDs
    uart_tx   : out std_logic;                       -- 8N1 serial output
    -- debug/observation ports (wires only, used by testbenches)
    dbg_pc    : out byte_t;
    dbg_flags : out std_logic_vector(3 downto 0);   -- Z N C V
    dbg_regs  : out regfile_t;
    dbg_ram   : out ram_t);
end entity cpu_top;

architecture rtl of cpu_top is
  -- Initial values keep the first delta cycle free of metavalue warnings.
  signal instr     : word_t := HALT_WORD;

  -- control
  signal reg_write, mem_read, mem_write, flag_write : std_logic := '0';
  signal alu_src_imm, rd2_from_rd, link, halt_int   : std_logic := '0';
  signal alu_op    : alu_op_t := ALU_ADD;
  signal wb_sel    : wb_sel_t := WB_ALU;
  signal pc_sel    : pc_sel_t := PC_NEXT;
  signal cond_code : cond_code_t := COND_JMP;

  -- datapath
  signal pc_q, pc_plus1, pc_target, br_target : byte_t := (others => '0');
  signal pc_load, eq, cond_taken : std_logic := '0';
  signal addr1, addr2, waddr     : regsel_t := (others => '0');
  signal rd1, rd2, alu_b, imm_ext : byte_t := (others => '0');
  signal alu_result, ram_data, wb_data : byte_t := (others => '0');
  signal ram_addr : byte_t := (others => '0');
  signal io_sel, mmio_we, ram_we_eff : std_logic := '0';
  signal io_rdata, mem_data : byte_t := (others => '0');
  signal z, c, n, v : std_logic := '0';
  signal flags_q    : std_logic_vector(3 downto 0) := (others => '0');
  signal flag_d     : std_logic_vector(3 downto 0) := (others => '0');
  signal rf_we, ram_we, flag_en : std_logic := '0';
begin

  pc_i : entity work.pc
    port map (clk => clk, rst => rst, en => not halt_int, load => pc_load,
              target => pc_target, q => pc_q);

  rom_i : entity work.instr_rom
    generic map (INIT => PROGRAM)
    port map (addr => pc_q, data => instr);

  ctl : entity work.control_unit
    port map (opcode => instr(15 downto 12), func => instr(2 downto 0),
              cond_code => instr(11 downto 8),
              reg_write => reg_write, mem_read => mem_read,
              mem_write => mem_write, flag_write => flag_write,
              alu_src_imm => alu_src_imm, rd2_from_rd => rd2_from_rd,
              alu_op => alu_op, wb_sel => wb_sel, pc_sel => pc_sel,
              cond_out => cond_code, link => link, halt => halt_int);

  -- Register port 1 reads rs; RET needs R7 on it instead.
  addr1 <= "111" when pc_sel = PC_R7 else instr(8 downto 6);
  -- Port 2 reads rt normally; BEQ/BNE and STORE put their second register in
  -- the rd field (bits 11:9).  See docs/ISA.md.
  addr2 <= instr(11 downto 9) when rd2_from_rd = '1' else instr(5 downto 3);
  -- CALL always writes R7, regardless of the encoded rd field.
  waddr <= "111" when link = '1' else instr(11 downto 9);

  -- Reset suppresses all architectural writes (PC/flags have their own reset).
  rf_we   <= reg_write and not rst;
  ram_we  <= mem_write and not rst;
  flag_en <= flag_write and not rst;

  rf : entity work.register_file
    port map (clk => clk, raddr1 => addr1, raddr2 => addr2,
              waddr => waddr, wdata => wb_data, we => rf_we,
              rd1 => rd1, rd2 => rd2, dbg => dbg_regs);

  -- ALU B input: register value or sign-extended imm6.
  imm_ext <= std_logic_vector(resize(signed(instr(5 downto 0)), 8));
  alu_b   <= imm_ext when alu_src_imm = '1' else rd2;

  alu_i : entity work.alu
    port map (a => rd1, b => alu_b, op => alu_op,
              result => alu_result, z => z, c => c, n => n, v => v);

  -- LOAD/STORE address = (rs + sext(imm6)) mod 256, computed by the ALU.
  ram_addr <= alu_result when (mem_read = '1' or mem_write = '1')
              else (others => '0');

  -- Address decoder: 0x00..0xEF -> data RAM, 0xF0..0xFF -> MMIO.  The
  -- comparison is numeric (unsigned), not lexicographic.  A LOAD/STORE in the
  -- I/O region must never write the corresponding data RAM byte.
  io_sel <= '1' when (mem_read = '1' or mem_write = '1') and
                     unsigned(ram_addr) >= unsigned(IO_BASE)
            else '0';
  ram_we_eff <= ram_we and not io_sel;
  mmio_we    <= ram_we and io_sel;

  ram_i : entity work.data_ram
    generic map (INIT => RAM_INIT)
    port map (clk => clk, we => ram_we_eff, addr => ram_addr,
              wdata => rd2, rdata => ram_data, dbg => dbg_ram);

  mmio_i : entity work.mmio
    generic map (CLK_FREQ => CLK_FREQ, BAUD => BAUD)
    port map (clk => clk, rst => rst, addr => ram_addr, we => mmio_we,
              wdata => rd2, rdata => io_rdata, gpio_in => gpio_in,
              gpio_out => gpio_out, uart_tx => uart_tx);

  -- Combinational read mux, still within the single-cycle LOAD path.
  mem_data <= io_rdata when io_sel = '1' else ram_data;

  flag_d <= z & n & c & v;   -- Z N C V
  flags_i : entity work.flag_reg
    port map (clk => clk, rst => rst, en => flag_en, d => flag_d, q => flags_q);

  flags_cond_i : entity work.branch_cond
    port map (flags => flags_q, cond => cond_code, taken => cond_taken);

  -- Writeback: ALU result / data RAM / PC+1 for the CALL link.
  with wb_sel select
    wb_data <= alu_result when WB_ALU,
               mem_data   when WB_MEM,
               pc_plus1   when WB_PC1;

  -- Branch condition for the Phase 1 register comparator.
  eq <= '1' when rd1 = rd2 else '0';

  -- Next-PC selection.
  pc_plus1  <= std_logic_vector(unsigned(pc_q) + 1);
  br_target <= std_logic_vector(unsigned(pc_plus1) + unsigned(imm_ext));

  pc_load <= '1' when (pc_sel = PC_ABS and cond_taken = '1')
                  or (pc_sel = PC_REL_EQ and eq = '1')
                  or (pc_sel = PC_REL_NE and eq = '0')
                  or  pc_sel = PC_R7
             else '0';

  with pc_sel select
    pc_target <= instr(7 downto 0) when PC_ABS,
                 br_target         when PC_REL_EQ | PC_REL_NE,
                 rd1               when PC_R7,
                 pc_plus1          when others;

  halted    <= halt_int;
  dbg_pc    <= pc_q;
  dbg_flags <= flags_q;

end architecture rtl;
